using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, quantities, shapes, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events, civilizations, and their impact." }
        };

        var instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Sarah Chen", Title = "Professor", Bio = "Dr. Chen has over 15 years of experience in software engineering and algorithms research. She holds a Ph.D. from MIT and has published extensively on distributed systems.", Email = "s.chen@university.edu" },
            new() { Id = 2, Name = "Dr. James Rodriguez", Title = "Associate Professor", Bio = "Dr. Rodriguez specializes in abstract algebra and number theory. He received his doctorate from Stanford and has won multiple teaching excellence awards.", Email = "j.rodriguez@university.edu" },
            new() { Id = 3, Name = "Dr. Emily Watson", Title = "Professor", Bio = "Dr. Watson is a leading researcher in quantum mechanics and particle physics. She previously worked at CERN before joining the faculty.", Email = "e.watson@university.edu" },
            new() { Id = 4, Name = "Dr. Michael Torres", Title = "Assistant Professor", Bio = "Dr. Torres focuses on modern American literature and creative writing. He is also a published novelist with three critically acclaimed books.", Email = "m.torres@university.edu" },
            new() { Id = 5, Name = "Dr. Lisa Park", Title = "Professor", Bio = "Dr. Park is an expert in medieval European history. She has led archaeological expeditions and authored several definitive texts on the subject.", Email = "l.park@university.edu" },
            new() { Id = 6, Name = "Dr. David Kim", Title = "Associate Professor", Bio = "Dr. Kim researches machine learning and artificial intelligence. He has industry experience at major tech companies and holds several patents.", Email = "d.kim@university.edu" }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Covers variables, control flow, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, DepartmentName = "Computer Science", Instructor = instructors[0], IsFeatured = true },
            new() { Id = 2, Code = "CS 301", Title = "Data Structures & Algorithms", Description = "In-depth study of data structures including trees, graphs, and hash tables. Analysis of algorithm complexity and design techniques.", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", DepartmentId = 1, DepartmentName = "Computer Science", Instructor = instructors[0], IsFeatured = false },
            new() { Id = 3, Code = "CS 450", Title = "Machine Learning", Description = "Introduction to machine learning concepts including supervised and unsupervised learning, neural networks, and model evaluation.", Credits = 3, Schedule = "Mon/Wed 2:00–3:30 PM", DepartmentId = 1, DepartmentName = "Computer Science", Instructor = instructors[5], IsFeatured = true },
            new() { Id = 4, Code = "MATH 201", Title = "Linear Algebra", Description = "Study of vector spaces, linear transformations, matrices, and eigenvalues. Applications to computer science and engineering.", Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentId = 2, DepartmentName = "Mathematics", Instructor = instructors[1], IsFeatured = false },
            new() { Id = 5, Code = "MATH 301", Title = "Abstract Algebra", Description = "Introduction to algebraic structures: groups, rings, and fields. Explores symmetry and structural properties of mathematical systems.", Credits = 3, Schedule = "Tue/Thu 1:00–2:30 PM", DepartmentId = 2, DepartmentName = "Mathematics", Instructor = instructors[1], IsFeatured = false },
            new() { Id = 6, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions. Calculus-based approach to fundamental physics.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Thu Lab 2:00–4:00 PM", DepartmentId = 3, DepartmentName = "Physics", Instructor = instructors[2], IsFeatured = true },
            new() { Id = 7, Code = "PHYS 410", Title = "Quantum Mechanics", Description = "Wave functions, Schrödinger equation, quantum states, and measurement theory. Prerequisite: PHYS 301.", Credits = 3, Schedule = "Tue/Thu 9:00–10:30 AM", DepartmentId = 3, DepartmentName = "Physics", Instructor = instructors[2], IsFeatured = false },
            new() { Id = 8, Code = "ENG 102", Title = "Composition & Rhetoric", Description = "Develop college-level writing skills through essays, research papers, and peer review. Emphasis on argumentation and clarity.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", DepartmentId = 4, DepartmentName = "English", Instructor = instructors[3], IsFeatured = false },
            new() { Id = 9, Code = "ENG 350", Title = "Modern American Literature", Description = "Survey of American literature from 1900 to present. Covers major movements, authors, and cultural contexts.", Credits = 3, Schedule = "Tue/Thu 3:00–4:30 PM", DepartmentId = 4, DepartmentName = "English", Instructor = instructors[3], IsFeatured = true },
            new() { Id = 10, Code = "HIST 201", Title = "World History: Medieval Period", Description = "Exploration of global civilizations from 500–1500 CE. Covers Europe, Asia, Africa, and the Americas.", Credits = 3, Schedule = "Mon/Wed 10:00–11:30 AM", DepartmentId = 5, DepartmentName = "History", Instructor = instructors[4], IsFeatured = false }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();
}

