                </div>
                <h2><a href="/courses/@course.Id">@course.Title</a></h2>
                <p>@course.Description</p>
                <div class="course-meta">
                    <span>📅 @course.Schedule</span>
                    <span>👤 @course.Instructor.Name</span>
                    <span>🏛️ @course.DepartmentName</span>
                </div>
            </div>
        }
    </div>
}

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }
}

@page "/courses/{Id:int}"
@inject UniversityCourseCatalog.Services.CatalogService CatalogService

@if (course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <h1>Course Not Found</h1>
    <p>The course you're looking for doesn't exist. <a href="/courses">Browse all courses</a>.</p>
}
else
{
    <PageTitle>@course.Code: @course.Title - University Course Catalog</PageTitle>

    <nav class="breadcrumb">
        <a href="/">Home</a> &rsaquo;
        <a href="/courses">Courses</a> &rsaquo;
        <a href="/courses?departmentId=@course.DepartmentId">@course.DepartmentName</a> &rsaquo;
        <span>@course.Code</span>
    </nav>

    <article class="course-detail">
        <header>
            <span class="badge large">@course.Code</span>
            <h1>@course.Title</h1>
        </header>

        <div class="detail-grid">
            <section class="detail-main">
                <h2>Description</h2>
                <p>@course.Description</p>

                <h2>Schedule</h2>
                <p>📅 @course.Schedule</p>

                <h2>Credits</h2>
                <p>@course.Credits credits</p>

                <div class="enroll-cta">
                    <a href="/enroll?courseId=@course.Id" class="btn btn-primary">Request Enrollment</a>
                </div>
            </section>

            <aside class="detail-sidebar">
                <div class="instructor-card">
                    <h3>Instructor</h3>
                    <p class="instructor-name">@course.Instructor.Name</p>
                    <p class="instructor-title">@course.Instructor.Title</p>
                    <p class="instructor-bio">@course.Instructor.Bio</p>
                    <p class="instructor-email">✉️ <a href="mailto:@course.Instructor.Email">@course.Instructor.Email</a></p>
                </div>
            </aside>
        </div>
    </article>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private UniversityCourseCatalog.Models.Course? course;

    protected override void OnInitialized()
    {
        course = CatalogService.GetCourse(Id);
    }
}

@page "/enroll"
@inject UniversityCourseCatalog.Services.CatalogService CatalogService

<PageTitle>Enrollment Request - University Course Catalog</PageTitle>

<h1>Enrollment Request</h1>

@if (Submitted)
{
    <div class="success-message">
        <h2>✅ Request Submitted</h2>
        <p>Thank you, <strong>@Model.StudentName</strong>! Your enrollment request has been received.</p>
        <p>You will receive a confirmation at your university email within 2–3 business days.</p>
        <a href="/courses" class="btn btn-primary">Browse More Courses</a>
    </div>
}
else
{
    <p>Fill out the form below to request enrollment in a course.</p>

    <form method="post" class="enroll-form">
        <AntiforgeryToken />

        <div class="form-group">
            <label for="studentName">Full Name</label>
            <input type="text" id="studentName" name="Model.StudentName" value="@Model.StudentName" required />
        </div>

        <div class="form-group">
            <label for="studentId">Student ID</label>
            <input type="text" id="studentId" name="Model.StudentId" value="@Model.StudentId" required placeholder="e.g., STU-123456" />
        </div>

        <div class="form-group">
            <label for="courseId">Course</label>
            <select id="courseId" name="Model.CourseId" required>
                <option value="">-- Select a course --</option>
                @foreach (var course in CatalogService.GetCourses())
                {
                    <option value="@course.Id" selected="@(Model.CourseId == course.Id)">@course.Code - @course.Title</option>
                }
            </select>
        </div>

        <button type="submit" class="btn btn-primary">Submit Request</button>
    </form>
}

@code {
    [SupplyParameterFromForm]
    public UniversityCourseCatalog.Models.EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    public bool Submitted { get; set; }

    protected override void OnInitialized()
    {
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    protected override void OnParametersSet()
    {
        // Check if form was submitted (POST with valid data)
        if (!string.IsNullOrWhiteSpace(Model.StudentName) &&
            !string.IsNullOrWhiteSpace(Model.StudentId) &&
            Model.CourseId > 0)
        {
            Submitted = true;
        }
    }
}

