+.instructor-name { font-weight: 600; font-size: 1.1rem; margin: 0; }
+.instructor-title { color: #666; margin: 0.2rem 0 0.8rem; }
+.instructor-bio { font-size: 0.9rem; color: #444; line-height: 1.5; }
+.instructor-email { margin-top: 0.8rem; font-size: 0.9rem; }
+
+/* === Enrollment Form === */
+.enroll-form {
+    max-width: 500px;
+    background: white;
+    padding: 2rem;
+    border-radius: 8px;
+    border: 1px solid #e0e0e0;
+}
+.form-group {
+    margin-bottom: 1.2rem;
+}
+.form-group label {
+    display: block;
+    font-weight: 600;
+    margin-bottom: 0.3rem;
+    font-size: 0.95rem;
+}
+.form-group input,
+.form-group select {
+    width: 100%;
+    padding: 0.6rem 0.8rem;
+    border: 1px solid #ccc;
+    border-radius: 6px;
+    font-size: 0.95rem;
+}
+
+.success-message {
+    background: #d4edda;
+    border: 1px solid #c3e6cb;
+    border-radius: 8px;
+    padding: 2rem;
+    max-width: 500px;
+}
+.success-message h2 { color: #155724; margin-bottom: 0.5rem; }
+.success-message p { color: #155724; }
+
+/* === Error === */
+.blazor-error-boundary {
+    background: url(data:image/svg+xml;base64,) no-repeat 1rem/1.8rem, #b32121;
+    padding: 1rem 1rem 1rem 3.7rem;
+    color: white;
